<template><div class="page-container"><div class="page-header"><h2>交易记录</h2></div><el-table :data="txs" border stripe v-loading="loading"><el-table-column prop="txHash" label="交易哈希" min-width="220"><template #default="{r}"><span style="font-family:monospace;font-size:12px">{{r.txHash?.substring(0,30)}}...</span></template></el-table-column><el-table-column prop="from" label="发送方" width="160"><template #default="{r}"><span style="font-family:monospace;font-size:12px">{{r.from?.substring(0,15)}}...</span></template></el-table-column><el-table-column prop="to" label="接收方" width="160"><template #default="{r}"><span style="font-family:monospace;font-size:12px">{{r.to?.substring(0,15)}}...</span></template></el-table-column><el-table-column prop="value" label="金额"/><el-table-column prop="blockNum" label="区块"/><el-table-column prop="status" label="状态" width="80"><template #default="{r}"><el-tag :type="r.status===1?'success':'danger'" size="small">{{r.status===1?'成功':'失败'}}</el-tag></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="total" layout="total,prev,pager,next" style="margin-top:16px" @current-change="loadData"/></div></template>
<script setup>import {ref,onMounted} from 'vue';import {blockchainApi} from '@/api';const loading=ref(false),txs=ref([]),page=ref(1),total=ref(0);onMounted(()=>loadData());async function loadData(){loading.value=true;try{const r=await blockchainApi.getTransactionList({page:page.value,pageSize:10});txs.value=r.data.list;total.value=r.data.total}catch(e){txs.value=[]}finally{loading.value=false}}</script>
